const f = doc.front;
const page = `<!doctype html>
<html lang="en" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Business Plan — BOUND Protocol</title>
<style>${rawCss}${docCss}${PRINT_CSS}</style></head><body>
<div class="layout">
<aside class="sidebar">
  <div class="sb-head">
    <div class="sb-title">${esc(f.kind)}</div>
    <div class="sb-sub">${esc(f.brand)}</div>
    <button class="sb-back" onclick="location.assign('/#docs')">&larr; Back to Library</button>
    ${PRINT_BUTTON}
  </div>
  <nav class="snav">${sidebarNav}</nav>
</aside>
<div class="content">
<div class="mast"><div class="mast-inner">
<div class="eyebrow">${esc(f.kind)}</div><h1>${esc(f.tagline)}</h1>
<p class="lede">${esc(f.brand)} — every figure derived from the simulation engine's default case.</p>
<div class="metarow">
<div><div class="k">Document</div><div class="v">${esc(f.kind)}</div></div>
<div><div class="k">Period</div><div class="v">${esc(f.version)}</div></div>
<div><div class="k">Protocol</div><div class="v">${esc(f.brand)}</div></div>
<div><div class="k">Origin</div><div class="v">${esc(f.place)}</div></div>
</div></div></div>
<div class="wrap">
${B}
<footer><div class="disc"><b>Note.</b> Every figure in this plan is derived from the BOUND simulation engine's default preset and from the verified operating cost model. Regenerate via <span class="mono">node scripts/sim-default-dump.mjs</span>, <span class="mono">python3 scripts/gen-costs-content.py</span>, <span class="mono">python3 scripts/gen-businessplan-content.py</span>, then <span class="mono">node scripts/build-businessplan.mjs</span>.</div>
<div>${esc(f.brand)} · ${esc(f.kind)} ${esc(f.version)} · ${esc(f.place)}</div></footer>
</div></div></div>
<script>(function(){
  var links=[].slice.call(document.querySelectorAll('.snav a[data-id]'));
  var secs=links.map(function(a){return document.getElementById(a.getAttribute('data-id'));});
  function spy(){var y=window.scrollY+150,cur=0;for(var i=0;i<secs.length;i++){if(secs[i]&&secs[i].offsetTop<=y)cur=i;}for(var j=0;j<links.length;j++){links[j].classList.toggle('active',j===cur);}}
  links.forEach(function(a){a.addEventListener('click',function(e){e.preventDefault();var el=document.getElementById(a.getAttribute('data-id'));if(el){el.scrollIntoView({behavior:'smooth',block:'start'});}});});
  window.addEventListener('scroll',spy,{passive:true});spy();
})();</script>
</body></html>`;

